-- Removes the video feature's table. The table was verified empty
-- (0 rows) with no foreign keys in either direction before this migration.
-- Rollback: restore the table from the pre-migration dump, or recreate it:
--   CREATE TABLE videos (
--     id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
--     created_at TIMESTAMP(6), updated_at TIMESTAMP(6),
--     display_order INTEGER NOT NULL, thumbnail_url VARCHAR(255),
--     title VARCHAR(255) NOT NULL, video_url VARCHAR(255) NOT NULL
--   );

BEGIN;

DO $$
BEGIN
  IF (SELECT COUNT(*) FROM videos) <> 0 THEN
    RAISE EXCEPTION 'videos table is not empty; aborting drop';
  END IF;
END $$;

DROP TABLE IF EXISTS videos;

COMMIT;
